const API='/api/naver-future-event-radar-20260928', KEY='naver_future_event_radar_access_v1';
let all=[],view=[],plan=null,theme='전체',sortMode='date',running=false,stopRequested=false,totalArticleCandidates=0;
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const fmt=n=>Number.isFinite(+n)?(+n).toLocaleString('ko-KR'):'-';
const dstr=iso=>{try{return new Date(iso).toLocaleDateString('ko-KR',{timeZone:'Asia/Seoul',year:'2-digit',month:'2-digit',day:'2-digit'})}catch{return iso||'-'}};
function auth(){return localStorage.getItem(KEY)||''}
function toast(s){$('pop').textContent=s;$('pop').classList.add('on');clearTimeout(toast.t);toast.t=setTimeout(()=>$('pop').classList.remove('on'),2200)}
async function doLogin(){const c=$('code').value.trim();$('loginErr').textContent='';if(!c)return $('loginErr').textContent='인증번호를 입력하세요.';try{const r=await fetch(API+'?mode=ping',{headers:{'x-access-code':c}});if(!r.ok)throw 0;localStorage.setItem(KEY,c);$('login').classList.add('hide');toast('인증되었습니다.');loadPlan()}catch{$('loginErr').textContent='인증번호가 맞지 않습니다.'}}
async function boot(){const c=auth();if(!c)return;try{const r=await fetch(API+'?mode=ping',{headers:{'x-access-code':c}});if(r.ok){$('login').classList.add('hide');loadPlan()}else localStorage.removeItem(KEY)}catch{}}
function resetAuth(){localStorage.removeItem(KEY);$('login').classList.remove('hide');$('code').value=''}
function params(mode){return new URLSearchParams({mode,trades:$('trades').value,pageDepth:$('depth').value,horizon:$('horizon').value})}
async function loadPlan(){try{const r=await fetch(API+'?'+params('plan'),{headers:{'x-access-code':auth()}}),j=await r.json();if(!r.ok||!j.ok)throw Error(j.error||'계획 조회 실패');plan=j;$('sUniverse').textContent=fmt(j.universeCount);$('meta').textContent=`검색 기준 ${j.range.start} ~ ${j.range.end} · ${j.trades}거래일 · ${j.windows}개 날짜구간 · ${j.terms}개 일정 검색어 · ${j.totalBatches}개 배치`;renderChips()}catch(e){$('meta').textContent='검색 계획을 불러오지 못했습니다: '+(e.message||e)}}
function stopScan(){stopRequested=true;$('progressText').textContent+=' · 중지 요청됨'}
function setRun(on){running=on;$('scanBtn').disabled=on;$('stopBtn').disabled=!on;$('trades').disabled=on;$('depth').disabled=on;$('horizon').disabled=on}
function mergeEvents(events){const map=new Map(all.map(x=>[x.id,x]));for(const x of events||[]){const old=map.get(x.id);if(old){const qs=new Set([...(old.queryTerms||[old.queryTerm]),x.queryTerm].filter(Boolean));old.queryTerms=[...qs];if(x.score>old.score)Object.assign(old,{score:x.score,stocks:x.stocks,sector:x.sector,themes:x.themes,eventType:x.eventType});}else{x.queryTerms=[x.queryTerm].filter(Boolean);map.set(x.id,x);}}all=[...map.values()]}
async function scanAll(){if(running)return;if(!auth())return $('login').classList.remove('hide');setRun(true);stopRequested=false;all=[];view=[];plan=null;totalArticleCandidates=0;theme='전체';render();renderChips();$('bar').style.width='0%';$('progressText').textContent='검색 범위와 종목 목록을 준비 중...';try{await loadPlan();if(!plan)throw Error('검색 계획을 만들지 못했습니다.');for(let b=0;b<plan.totalBatches;b++){if(stopRequested)break;$('progressText').textContent=`네이버 뉴스 검색 ${b+1} / ${plan.totalBatches} · 발견 일정 ${fmt(all.length)}건`;const p=params('batch');p.set('batch',String(b));const r=await fetch(API+'?'+p,{headers:{'x-access-code':auth()}}),j=await r.json();if(!r.ok||!j.ok)throw Error(j.error||`배치 ${b+1} 검색 실패`);totalArticleCandidates+=j.articleCount||0;mergeEvents(j.events);$('bar').style.width=`${Math.round((b+1)/plan.totalBatches*100)}%`;renderChips();render();await new Promise(res=>setTimeout(res,80));}$('progressText').textContent=stopRequested?`검색 중지 · 현재 ${fmt(all.length)}건 보관`:`검색 완료 · 미래 일정 뉴스 ${fmt(all.length)}건`;if(!stopRequested)toast('전체 검색이 끝났습니다.')}catch(e){$('progressText').textContent='검색 오류: '+(e.message||e);toast('검색 중 오류가 발생했습니다.')}finally{setRun(false);render()}}
function filters(){const q=$('q').value.trim().toLowerCase(),min=+$('minScore').value,prec=$('precision').value;let r=all.filter(x=>x.score>=min&&(prec==='ALL'||x.precision===prec)&&(theme==='전체'||(x.themes||[]).includes(theme)||x.sector===theme));if(q)r=r.filter(x=>`${x.title} ${x.snippet} ${x.source} ${x.eventDate} ${x.displayDate} ${x.eventType} ${x.sector} ${(x.themes||[]).join(' ')} ${(x.stocks||[]).map(s=>s.name+' '+s.code).join(' ')}`.toLowerCase().includes(q));r.sort(sortMode==='score'?(a,b)=>b.score-a.score||a.eventDate.localeCompare(b.eventDate):(a,b)=>a.eventDate.localeCompare(b.eventDate)||b.score-a.score);return r}
function renderChips(){const c={};for(const x of all){for(const t of x.themes||[])c[t]=(c[t]||0)+1;if(x.sector)c[x.sector]=(c[x.sector]||0)+1}const items=['전체',...Object.keys(c).sort((a,b)=>c[b]-c[a]).slice(0,28)];$('chips').innerHTML=items.map(t=>`<button class="chip ${theme===t?'on':''}" onclick="theme=${JSON.stringify(t)};renderChips();render()">${esc(t)}${t==='전체'?'':` ${fmt(c[t])}`}</button>`).join('')}
function render(){view=filters();const stockCodes=new Set(),exact=all.filter(x=>x.precision==='day').length,soon=all.filter(x=>x.dDay>=1&&x.dDay<=30).length;for(const x of all)for(const s of x.stocks||[])stockCodes.add(s.code);$('sEvents').textContent=fmt(all.length);$('sExact').textContent=fmt(exact);$('sStocks').textContent=fmt(stockCodes.size);$('sSoon').textContent=fmt(soon);$('sArticles').textContent=fmt(totalArticleCandidates);if(!view.length){$('tbody').innerHTML=`<tr><td colspan="12" class="empty">${all.length?'현재 필터에 맞는 결과가 없습니다.':'아직 발견된 일정 뉴스가 없습니다.'}</td></tr>`;return}$('tbody').innerHTML=view.map(x=>{const dd=x.dDay===0?'D-DAY':x.dDay>0?'D-'+x.dDay:'D+'+Math.abs(x.dDay),stocks=(x.stocks||[]).length?(x.stocks||[]).map(s=>`<a class="stock" target="_blank" rel="noopener" href="${esc(s.naver)}">${esc(s.name)} <small>${esc(s.code)} · ${esc(s.market)}</small></a>`).join(''):'<span class="muted">직접 연결 없음</span>',themes=(x.themes||[]).length?(x.themes||[]).map(t=>`<span class="theme">${esc(t)}</span>`).join(''):'<span class="muted">-</span>',news=x.naverNewsUrl||x.naverSearchUrl,newsLabel=x.naverNewsUrl?'네이버뉴스':'네이버에서 찾기';return `<tr><td class="dday ${x.dDay<=7?'soon':''} nowrap">${dd}</td><td class="nowrap"><span class="date">${esc(x.displayDate||x.eventDate)}</span><br><span class="precision">${esc(x.precision)} · ${esc(x.dateText||'')}</span></td><td class="score ${x.score>=85?'hi':''}">${x.score}</td><td class="event nowrap">${esc(x.eventType)}</td><td class="sector nowrap">${esc(x.sector)}</td><td>${themes}</td><td class="stocks">${stocks}</td><td class="title"><b>${esc(x.title)}</b><div class="snippet">${esc(x.snippet||'')}</div></td><td class="nowrap">${esc(x.source||'-')}</td><td class="nowrap">${dstr(x.publishedAt)}</td><td class="nowrap"><a class="link naver" target="_blank" rel="noopener" href="${esc(news)}">${newsLabel}</a>${x.originUrl&&x.originUrl!==news?`<br><a class="link origin" target="_blank" rel="noopener" href="${esc(x.originUrl)}">원문</a>`:''}</td><td>${esc((x.queryTerms||[x.queryTerm]).join(', '))}</td></tr>`}).join('')}
function downloadXlsx(){if(!all.length)return toast('저장할 검색 결과가 없습니다.');if(typeof XLSX==='undefined')return toast('Excel 모듈을 불러오지 못했습니다.');const rows=filters().map(x=>({D_Day:x.dDay,일정일:x.eventDate,표시일정:x.displayDate,날짜정밀도:x.precision,기사속날짜표현:x.dateText,신뢰점수:x.score,이벤트유형:x.eventType,섹터:x.sector,테마:(x.themes||[]).join(', '),연결종목:(x.stocks||[]).map(s=>s.name).join(', '),종목코드:(x.stocks||[]).map(s=>s.code).join(', '),시장:(x.stocks||[]).map(s=>s.market).join(', '),뉴스제목:x.title,요약:x.snippet,언론사:x.source,기사일:x.publishedAt,네이버뉴스:x.naverNewsUrl||x.naverSearchUrl,원문:x.originUrl,검색어:(x.queryTerms||[x.queryTerm]).join(', ')}));const stockRows=[];for(const x of filters())for(const s of x.stocks||[])stockRows.push({일정일:x.eventDate,D_Day:x.dDay,종목:s.name,코드:s.code,시장:s.market,현재가:s.price,등락률:s.changePct,섹터:x.sector,테마:(x.themes||[]).join(', '),이벤트:x.eventType,뉴스제목:x.title,네이버증권:s.naver,네이버뉴스:x.naverNewsUrl||x.naverSearchUrl});const info=[{생성시각:new Date().toLocaleString('ko-KR'),뉴스검색기간:plan?`${plan.range.start} ~ ${plan.range.end}`:'',거래일:plan?.trades||$('trades').value,검색깊이:$('depth').value,앞으로일정범위_일:$('horizon').value,검색된일정뉴스:all.length,현재필터결과:view.length,종목매핑대상:plan?.universeCount||'',설명:'네이버 뉴스 검색 노출 결과를 날짜구간·일정검색어별로 수집해 미래 날짜를 추출한 결과'}];const wb=XLSX.utils.book_new(),ws=XLSX.utils.json_to_sheet(rows);ws['!cols']=[8,12,15,11,16,10,18,16,28,28,18,14,55,65,16,23,55,55,30].map(w=>({wch:w}));XLSX.utils.book_append_sheet(wb,ws,'일정뉴스');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(stockRows),'종목연결');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(info),'검색정보');const k=new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Seoul'}).replaceAll('-','');XLSX.writeFile(wb,`NAVER_미래일정_뉴스레이더_${k}.xlsx`);toast('Excel 파일을 저장했습니다.')}
$('trades').addEventListener('change',loadPlan);$('depth').addEventListener('change',loadPlan);$('horizon').addEventListener('change',loadPlan);$('precision').addEventListener('change',render);$('minScore').addEventListener('change',render);document.addEventListener('keydown',e=>{if(e.key==='Enter'&&!$('login').classList.contains('hide'))doLogin()});boot();
